-- Asset Avengers trading platform mock data
-- This script is idempotent and can be run multiple times safely.
-- Uses ON CONFLICT DO NOTHING to prevent duplicate data.

-- ============================================================
-- USERS (8 entries: 2 admins, 3 analysts, 3 clients)
-- ============================================================
ON CONFLICT (user_id) DO NOTHING;

-- ============================================================
-- INSTRUMENTS (25 entries)
-- ============================================================
ON CONFLICT (symbol) DO NOTHING;

-- ============================================================
-- ACCOUNTS (6 entries - for clients and analysts, not admins)
-- ============================================================
ON CONFLICT (account_id) DO NOTHING;

-- ============================================================
-- ORDERS (35 entries)
-- ============================================================
ON CONFLICT (order_id) DO NOTHING;

-- ============================================================
-- TRANSACTIONS (15 entries)
-- ============================================================
ON CONFLICT (transaction_id) DO NOTHING;

-- ============================================================
-- HOLDINGS (11 entries)
-- ============================================================
ON CONFLICT (holding_id) DO NOTHING;

-- Summary: 8 users + 25 instruments + 6 accounts + 35 orders + 15 transactions + 11 holdings = 100 mock data entries
